local ids={__IDS__} local out,bad={},0 for i,d in ids do local im local ok,r=pcall(function() return game:GetObjects("rbxassetid://"..d)[1] end) if ok and r then local t=r:IsA("Decal") and r.Texture or (r:FindFirstChildWhichIsA("Decal",true) and r:FindFirstChildWhichIsA("Decal",true).Texture) or "" im=string.match(t,"%d+$") r:Destroy() end if im then table.insert(out,d.."="..im) else bad+=1 table.insert(out,d.."=?") end if i%20==0 then print("Capeline ids",i,"of",#ids) end end local m=Instance.new("ModuleScript") m.Name="CapelineImageIds" m.Source="CAPELINE IMAGE IDS "..#ids.." missing "..bad.."\n"..table.concat(out,",") m.Parent=workspace print("Capeline ids done,",bad,"missing. Open Workspace > CapelineImageIds") pcall(function() game:GetService("ScriptEditorService"):OpenScriptDocumentAsync(m) end)
